type Row=Record<string,any>;
export class HubError extends Error{constructor(public status:number,message:string){super(message);}}
export const projects=[{id:'moso-connect-2',name:'모소 커넥트2.0'},{id:'moso-growth',name:'모소 그로스 웹사이트'},{id:'ai-creator-studio',name:'AI 크리에이터 스튜디오'},{id:'ai-creator-manager',name:'AI 크리에이터 매니져'},{id:'sns-channel-manager',name:'SNS 채널 매니져'},{id:'sandbox',name:'기존 회의 · 통신 테스트'},{id:'moso',name:'기존 회의 · MOSO'},{id:'onlyfive',name:'기존 회의 · OnlyFive'}];
// Cache completed initialization only. Sharing a pending D1 promise between
// Worker requests can leave later browser reads tied to a cancelled request.
let studioSchemaReady=false;
export async function ensureStudioSchema(){if(studioSchemaReady)return;const db=database();await db.batch([
 db.prepare("CREATE TABLE IF NOT EXISTS hub_project_archives (id text PRIMARY KEY,name text NOT NULL,deleted_at text NOT NULL,deletion_key text NOT NULL)"),
 db.prepare("CREATE TABLE IF NOT EXISTS hub_project_archive_rooms (project text NOT NULL,room_id text NOT NULL,PRIMARY KEY(project,room_id))"),
 db.prepare("CREATE TABLE IF NOT EXISTS hub_projects (id text PRIMARY KEY NOT NULL,name text NOT NULL COLLATE NOCASE UNIQUE,created_at text NOT NULL)"),
 db.prepare("CREATE TABLE IF NOT EXISTS hub_studio_keys (id text PRIMARY KEY NOT NULL,project text NOT NULL,hash text NOT NULL,enabled integer DEFAULT 1 NOT NULL,last_seen text,created_at text NOT NULL)"),
 db.prepare("CREATE UNIQUE INDEX IF NOT EXISTS hub_studio_key_hash ON hub_studio_keys(hash)"),
 db.prepare("CREATE TABLE IF NOT EXISTS hub_production_jobs (id text PRIMARY KEY NOT NULL,room_id text NOT NULL,project text NOT NULL,title text NOT NULL,mode text NOT NULL,prompt text NOT NULL,negative text DEFAULT '' NOT NULL,aspect text DEFAULT '9:16' NOT NULL,quality text DEFAULT 'high' NOT NULL,duration integer DEFAULT 10 NOT NULL,seed integer DEFAULT 42 NOT NULL,guidance integer DEFAULT 1 NOT NULL,resolution text NOT NULL,model text,status text NOT NULL,approved_by text,approved_at text,lease_id text,expires integer,studio_job_id text,result text,error text,created_at text NOT NULL,updated_at text NOT NULL,FOREIGN KEY(room_id) REFERENCES hub_rooms(id))"),
 db.prepare("CREATE INDEX IF NOT EXISTS hub_production_project_status ON hub_production_jobs(project,status)"),
 db.prepare("CREATE INDEX IF NOT EXISTS hub_production_room ON hub_production_jobs(room_id,created_at)"),
 db.prepare("CREATE TABLE IF NOT EXISTS hub_studio_progress_reports (id text PRIMARY KEY NOT NULL,room_id text NOT NULL,project text NOT NULL,body text NOT NULL,created_at text NOT NULL)"),
 db.prepare("CREATE INDEX IF NOT EXISTS hub_progress_report_room ON hub_studio_progress_reports(project,room_id,created_at)"),
 db.prepare("CREATE TABLE IF NOT EXISTS hub_studio_progress (room_id text NOT NULL,project text NOT NULL,last_report_ms integer NOT NULL,PRIMARY KEY(room_id,project))"),
 db.prepare("CREATE TABLE IF NOT EXISTS hub_publication_jobs (id text PRIMARY KEY NOT NULL,production_id text NOT NULL UNIQUE,room_id text NOT NULL,project text NOT NULL,platform text NOT NULL,account text NOT NULL,caption text NOT NULL,status text NOT NULL,approved_by text NOT NULL,approved_at text NOT NULL,lease_id text,expires integer,attempts integer DEFAULT 0 NOT NULL,result text,error text,created_at text NOT NULL,updated_at text NOT NULL,FOREIGN KEY(production_id) REFERENCES hub_production_jobs(id),FOREIGN KEY(room_id) REFERENCES hub_rooms(id))"),
 db.prepare("CREATE INDEX IF NOT EXISTS hub_publication_project_status ON hub_publication_jobs(project,status)"),
 db.prepare("CREATE TABLE IF NOT EXISTS hub_meeting_reports (id text PRIMARY KEY NOT NULL,room_id text NOT NULL,project text NOT NULL,source_message_id text NOT NULL UNIQUE,summary text NOT NULL,decision text NOT NULL,status text DEFAULT 'pending' NOT NULL,created_at text NOT NULL,updated_at text NOT NULL,FOREIGN KEY(room_id) REFERENCES hub_rooms(id))"),
 db.prepare("CREATE INDEX IF NOT EXISTS hub_meeting_reports_room ON hub_meeting_reports(room_id,created_at)"),
 db.prepare("CREATE TABLE IF NOT EXISTS hub_action_items (id text PRIMARY KEY NOT NULL,report_id text NOT NULL,room_id text NOT NULL,project text NOT NULL,ordinal integer NOT NULL,title text NOT NULL,description text NOT NULL,action_type text NOT NULL,assignee text NOT NULL,payload text,status text DEFAULT 'pending' NOT NULL,production_job_id text,error text,approved_by text,approved_at text,created_at text NOT NULL,updated_at text NOT NULL,FOREIGN KEY(report_id) REFERENCES hub_meeting_reports(id),FOREIGN KEY(room_id) REFERENCES hub_rooms(id),FOREIGN KEY(production_job_id) REFERENCES hub_production_jobs(id),UNIQUE(report_id,ordinal))"),
 db.prepare("CREATE INDEX IF NOT EXISTS hub_action_items_room_status ON hub_action_items(room_id,status)"),
 db.prepare("CREATE TABLE IF NOT EXISTS hub_project_memory (project text PRIMARY KEY NOT NULL,summary text NOT NULL,sources text NOT NULL,updated_by text NOT NULL,created_at text NOT NULL,updated_at text NOT NULL)"),
 db.prepare("CREATE TABLE IF NOT EXISTS hub_external_agents (project text NOT NULL,agent text NOT NULL,enabled integer DEFAULT 1 NOT NULL,last_seen text NOT NULL,created_at text NOT NULL,PRIMARY KEY(project,agent))"),
 db.prepare("CREATE TABLE IF NOT EXISTS hub_asset_namespaces(project text NOT NULL,kind text NOT NULL,id text NOT NULL,storage_project text NOT NULL,PRIMARY KEY(project,kind,id))"),
 db.prepare("CREATE TABLE IF NOT EXISTS hub_room_origins(room_id text NOT NULL,project text NOT NULL,PRIMARY KEY(room_id,project))"),
]);studioSchemaReady=true;}
export async function assetStorageProject(pid:string,kind:'production'|'reference',id:string){await ensureStudioSchema();const row=await database().prepare('SELECT storage_project FROM hub_asset_namespaces WHERE project=? AND kind=? AND id=?').bind(pid,kind,id).first<{storage_project:string}>();return row?.storage_project||pid;}
export const stamp=()=>new Date().toISOString();
export const uid=()=>crypto.randomUUID();
export function database(){if(!env.DB)throw new HubError(503,'대화 저장소 연결을 확인하고 있습니다.');return env.DB;}
export async function listProjects(){await ensureStudioSchema();const saved=await database().prepare('SELECT id,name FROM hub_projects ORDER BY rowid').all<Row>();const archived=await database().prepare('SELECT id FROM hub_project_archives').all<Row>(),hidden=new Set(archived.results.map(p=>p.id));return [...projects.map(p=>({...p,name:saved.results.find(row=>row.id===p.id)?.name||p.name})),...saved.results.filter(p=>!projects.some(defaultProject=>defaultProject.id===p.id))].filter(p=>!hidden.has(p.id));}
export async function project(value:unknown){if(typeof value!=='string'||!(await listProjects()).some(p=>p.id===value))throw new HubError(400,'프로젝트를 선택해주세요.');return value;}
export async function projectTrash(){await ensureStudioSchema();return (await database().prepare('SELECT id,name,deleted_at FROM hub_project_archives ORDER BY deleted_at DESC').all<Row>()).results;}
export async function archiveProject(actor:string,pid:string){await ensureStudioSchema();const item=(await listProjects()).find(p=>p.id===pid);if(!item)throw new HubError(404,'프로젝트를 찾을 수 없습니다.');const db=database(),key=uid(),now=stamp();const result=await db.batch([
 db.prepare("INSERT OR IGNORE INTO hub_project_archives SELECT ?,?,?,? WHERE NOT EXISTS(SELECT 1 FROM hub_production_jobs WHERE project=? AND status IN ('queued','running')) AND NOT EXISTS(SELECT 1 FROM hub_publication_jobs WHERE project=? AND status IN ('queued','leased'))").bind(pid,item.name,now,key,pid,pid),
 db.prepare("INSERT OR IGNORE INTO hub_project_archive_rooms SELECT ?,id FROM hub_rooms WHERE project=? AND status!='deleted' AND EXISTS(SELECT 1 FROM hub_project_archives WHERE id=? AND deletion_key=?)").bind(pid,pid,pid,key),
 db.prepare("UPDATE hub_rooms SET status='deleted',updated_at=? WHERE project=? AND id IN (SELECT room_id FROM hub_project_archive_rooms WHERE project=?) AND EXISTS(SELECT 1 FROM hub_project_archives WHERE id=? AND deletion_key=?)").bind(now,pid,pid,pid,key),
 db.prepare("UPDATE hub_deliveries SET status='cancelled',lease_id=NULL,expires=NULL WHERE room_id IN (SELECT room_id FROM hub_project_archive_rooms WHERE project=?) AND status IN ('pending','leased') AND EXISTS(SELECT 1 FROM hub_project_archives WHERE id=? AND deletion_key=?)").bind(pid,pid,key),
 ]);if(!result[0].meta.changes)throw new HubError(409,'진행 중인 제작·게시 작업이 있어 프로젝트를 삭제할 수 없습니다. 해당 작업을 먼저 확인해주세요.');await event(actor,pid,'project.archive',pid);return {ok:true,recoverable:true};}
export async function restoreProject(actor:string,idValue:unknown){await ensureStudioSchema();const id=text(idValue,'프로젝트 ID',100),db=database();if(!await db.prepare('SELECT id FROM hub_project_archives WHERE id=?').bind(id).first())throw new HubError(404,'삭제된 프로젝트를 찾을 수 없습니다.');await db.batch([db.prepare("UPDATE hub_rooms SET status='paused',updated_at=? WHERE project=? AND status='deleted' AND id IN (SELECT room_id FROM hub_project_archive_rooms WHERE project=?)").bind(stamp(),id,id),db.prepare('DELETE FROM hub_project_archive_rooms WHERE project=?').bind(id),db.prepare('DELETE FROM hub_project_archives WHERE id=?').bind(id)]);await event(actor,id,'project.restore',id);return {ok:true};}
export async function sidebarState(){await ensureStudioSchema();const db=database(),projects=await listProjects();const [rows,recent]=await Promise.all([db.prepare("SELECT * FROM (SELECT id,title,project,rowid AS cursor,ROW_NUMBER() OVER(PARTITION BY project ORDER BY rowid DESC) AS ordinal,COUNT(*) OVER(PARTITION BY project) AS total FROM hub_rooms WHERE status!='deleted') WHERE ordinal<=20 ORDER BY cursor DESC").all<Row>(),db.prepare("SELECT id,title,project,rowid AS cursor FROM hub_rooms WHERE status!='deleted' ORDER BY rowid DESC LIMIT 20").all<Row>()]);return {projects:projects.map(p=>{const rooms=rows.results.filter(r=>r.project===p.id);return {...p,rooms,total:rooms[0]?.total||0,cursor:Number(rooms[0]?.total||0)>rooms.length?rooms.at(-1)?.cursor:null};}),recent:recent.results};}
export async function sidebarPage(pid:string,before:number|null){await ensureStudioSchema();const rows=await database().prepare("SELECT id,title,project,rowid AS cursor FROM hub_rooms WHERE project=? AND status!='deleted' AND rowid<? ORDER BY rowid DESC LIMIT 21").bind(pid,before||Number.MAX_SAFE_INTEGER).all<Row>();return {rooms:rows.results.slice(0,20),cursor:rows.results.length>20?rows.results[19].cursor:null};}
export async function createProject(actor:string,nameValue:unknown){await ensureStudioSchema();const name=text(nameValue,'프로젝트 이름',80).normalize('NFKC');if((await projectTrash()).some(p=>p.name.toLocaleLowerCase()===name.toLocaleLowerCase()))throw new HubError(409,'같은 이름의 프로젝트가 휴지통에 있습니다. 먼저 복원해주세요.');const existing=(await listProjects()).find(p=>p.name.toLocaleLowerCase()===name.toLocaleLowerCase());if(existing)return {project:existing,created:false};const id='p-'+uid(),result=await database().prepare('INSERT OR IGNORE INTO hub_projects(id,name,created_at) VALUES(?,?,?)').bind(id,name,stamp()).run();const saved=await database().prepare('SELECT id,name FROM hub_projects WHERE name=? COLLATE NOCASE').bind(name).first<Row>();if(!saved)throw new HubError(409,'프로젝트를 추가하지 못했습니다.');if(result.meta.changes)await event(actor,saved.id,'project.created',saved.id);return {project:saved,created:!!result.meta.changes};}
export async function renameProject(actor:string,idValue:unknown,nameValue:unknown){
 const id=await project(idValue),name=text(nameValue,'프로젝트 이름',80).normalize('NFKC'),list=await listProjects();
 if(list.some(p=>p.id!==id&&p.name.toLocaleLowerCase()===name.toLocaleLowerCase())||(await projectTrash()).some(p=>p.id!==id&&p.name.toLocaleLowerCase()===name.toLocaleLowerCase()))throw new HubError(409,'같은 이름의 프로젝트가 있습니다.');
 try{await database().prepare('INSERT INTO hub_projects(id,name,created_at) VALUES(?,?,?) ON CONFLICT(id) DO UPDATE SET name=excluded.name').bind(id,name,stamp()).run();}catch{throw new HubError(409,'프로젝트 이름을 저장하지 못했습니다. 같은 이름이 있는지 확인해주세요.');}
 await event(actor,id,'project.rename',id);return {ok:true,project:{id,name}};
}
export function text(value:unknown,name:string,max=6000){if(typeof value!=='string'||!value.trim()||value.length>max)throw new HubError(400,`${name}을 확인해주세요.`);return value.trim();}
export async function hash(value:string){return Array.from(new Uint8Array(await crypto.subtle.digest('SHA-256',new TextEncoder().encode(value))),n=>n.toString(16).padStart(2,'0')).join('');}
export function owner(req:Request){const id=req.headers.get('oai-authenticated-user-id');if(!id)throw new HubError(401,'치프의 ChatGPT 로그인이 필요합니다.');return id;}
export function sameOrigin(req:Request){const o=req.headers.get('origin');if(o&&o!==new URL(req.url).origin)throw new HubError(403,'허용되지 않은 요청입니다.');}
export async function body(req:Request){if(Number(req.headers.get('content-length')||0)>24000)throw new HubError(413,'메시지가 너무 깁니다.');if(!(req.headers.get('content-type')||'').startsWith('application/json'))throw new HubError(415,'JSON 요청이 필요합니다.');const raw=await req.text();if(new TextEncoder().encode(raw).length>24000)throw new HubError(413,'메시지가 너무 깁니다.');let b;try{b=JSON.parse(raw);}catch{throw new HubError(400,'요청을 읽을 수 없습니다.');}if(!b||Array.isArray(b)||typeof b!=='object')throw new HubError(400,'요청 형식을 확인해주세요.');return b;}
export function response(data:any,status=200){return Response.json(data,{status,headers:{'Cache-Control':'no-store','X-Content-Type-Options':'nosniff','Referrer-Policy':'no-referrer'}});}
export async function event(actor:string,pid:string,action:string,target:string|null=null){await database().prepare('INSERT INTO hub_audit(id,actor,project,action,target,created_at) VALUES(?,?,?,?,?,?)').bind(uid(),actor,pid,action,target,stamp()).run();}
export async function muse(req:Request){const auth=req.headers.get('authorization')||'';if(!/^Bearer vh_[A-Za-z0-9_-]{43}$/.test(auth))throw new HubError(401,'뮤즈 전용 연결 토큰이 필요합니다.');const key=await database().prepare('SELECT * FROM hub_agent_keys WHERE hash=? AND enabled=1').bind(await hash(auth.slice(7))).first<Row>();if(!key)throw new HubError(401,'연결 토큰이 만료되었거나 폐기됐습니다.');await database().prepare('UPDATE hub_agent_keys SET last_seen=? WHERE id=? AND enabled=1').bind(stamp(),key.id).run();return key;}
export function cursor(value:unknown){if(value===undefined||value===null||value==='')return null;const n=Number(value);if(!Number.isSafeInteger(n)||n<1)throw new HubError(400,'기록 위치를 확인해주세요.');return n;}
export async function history(pid:string,rid:string,before:number|null=null){
  const db=database(),room=await db.prepare("SELECT id FROM hub_rooms WHERE id=? AND project=? AND status!='deleted'").bind(text(rid,'대화 ID',100),pid).first();
  if(!room)throw new HubError(404,'이 프로젝트의 대화를 찾을 수 없습니다.');
  const rows=await db.prepare('SELECT *,rowid AS cursor FROM hub_messages WHERE room_id=? AND project=? AND NOT (sender=\'studio\' AND body LIKE \'스튜디오 진행상황 · 5분 업데이트%\') AND rowid<? ORDER BY rowid DESC LIMIT 101').bind(rid,pid,before||Number.MAX_SAFE_INTEGER).all<Row>();
  const page=rows.results.slice(0,100);return {messages:page.reverse(),nextCursor:rows.results.length>100?page[0].cursor:null};
}
export async function state(pid:string,rid:string|null=null,before:number|null=null){await ensureStudioSchema();const db=database();const [rr,keys,jobs,projectMemory,externalAgents]=await Promise.all([
  db.prepare("SELECT *,rowid AS cursor FROM hub_rooms WHERE project=? AND status!='deleted' AND rowid<? ORDER BY rowid DESC LIMIT 31").bind(pid,before||Number.MAX_SAFE_INTEGER).all<Row>(),
  db.prepare('SELECT id,last_seen FROM hub_agent_keys WHERE project=? AND enabled=1').bind(pid).all<Row>(),
  db.prepare("SELECT g.room_id,g.status,g.error,g.created_at FROM hub_generations g JOIN hub_rooms r ON r.id=g.room_id WHERE r.project=? AND g.status!='completed' AND g.status NOT LIKE 'gemini_%' AND r.status!='deleted' ORDER BY g.created_at DESC LIMIT 30").bind(pid).all(),
  db.prepare('SELECT summary,sources,updated_at FROM hub_project_memory WHERE project=?').bind(pid).first<Row>(),
  db.prepare('SELECT agent,last_seen,enabled FROM hub_external_agents WHERE project=?').bind(pid).all<Row>(),
]);
 const rooms=rr.results.slice(0,30),roomCursor=rr.results.length>30?rooms.at(-1)!.cursor:null;
 if(rid&&!rooms.some(r=>r.id===rid)){const selected=await db.prepare("SELECT *,rowid AS cursor FROM hub_rooms WHERE id=? AND project=? AND status!='deleted'").bind(rid,pid).first<Row>();if(!selected)throw new HubError(404,'이 프로젝트의 대화를 찾을 수 없습니다.');rooms.push(selected);}
 const selectedRoomId=rid||rooms[0]?.id||null,mm=selectedRoomId?await history(pid,selectedRoomId):{messages:[],nextCursor:null};
 const [productions,studioKeys,publications,reports,actionItems]=await Promise.all([
  selectedRoomId?db.prepare('SELECT * FROM hub_production_jobs WHERE room_id=? AND project=? ORDER BY rowid DESC LIMIT 30').bind(selectedRoomId,pid).all<Row>():Promise.resolve({results:[]}),
  db.prepare('SELECT last_seen FROM hub_studio_keys WHERE project=? AND enabled=1').bind(pid).all<Row>(),
  selectedRoomId?db.prepare('SELECT * FROM hub_publication_jobs WHERE room_id=? AND project=? ORDER BY rowid DESC LIMIT 30').bind(selectedRoomId,pid).all<Row>():Promise.resolve({results:[]}),
  selectedRoomId?db.prepare('SELECT * FROM hub_meeting_reports WHERE room_id=? AND project=? ORDER BY rowid DESC LIMIT 10').bind(selectedRoomId,pid).all<Row>():Promise.resolve({results:[]}),
  selectedRoomId?db.prepare('SELECT * FROM hub_action_items WHERE room_id=? AND project=? ORDER BY rowid').bind(selectedRoomId,pid).all<Row>():Promise.resolve({results:[]}),
 ]);
 const publicationByProduction=new Map(publications.results.map(p=>[p.production_id,{id:p.id,platform:p.platform,account:p.account,caption:p.caption,status:p.status,result:p.result?JSON.parse(p.result):null,error:p.error,approvedAt:p.approved_at}]));
 const actionsByReport=new Map<string,Row[]>();for(const item of actionItems.results){const list=actionsByReport.get(item.report_id)||[];let payload=null;try{payload=item.payload?JSON.parse(item.payload):null;}catch{}list.push({...item,payload:rebaseAssetLinks(payload,pid)});actionsByReport.set(item.report_id,list);}
 let memorySources:string[]=[];try{memorySources=projectMemory?.sources?JSON.parse(projectMemory.sources):[];}catch{}
 const apiAgents=await apiParticipantState(pid,selectedRoomId),openai=await openAIConnection();
 const external=(agent:string)=>{if(apiAgents[agent]?.configured)return apiAgents[agent];const row=externalAgents.results.find(a=>a.agent===agent&&a.enabled);return {configured:!!row,online:!!row&&Date.now()-Date.parse(row.last_seen)<300000,lastSeen:row?.last_seen||null,mode:'login_connector'};};
 return {projects:await listProjects(),rooms:rooms.map(r=>({...r,max_turns:null})),roomCursor,selectedRoomId,messages:mm.messages,messageCursor:mm.nextCursor,projectMemory:projectMemory?{summary:projectMemory.summary,sources:memorySources,updatedAt:projectMemory.updated_at}:null,muse:{configured:keys.results.length>0,online:keys.results.some(k=>k.last_seen&&Date.now()-Date.parse(k.last_seen)<180000),lastSeen:keys.results.map(k=>k.last_seen).filter(Boolean).sort().at(-1)||null},gemini:apiAgents.gemini,claude:external('claude'),grok:external('grok'),director:{configured:!!openai.key,connectionSource:openai.source,model:env.OPENAI_MODEL||'gpt-5.4-mini',automatic:true,notice:env.OPENAI_SERVICE_NOTICE||null},studio:{configured:studioKeys.results.length>0,online:studioKeys.results.some(k=>k.last_seen&&Date.now()-Date.parse(k.last_seen)<180000)},reports:reports.results.map(r=>({...r,actions:actionsByReport.get(r.id)||[]})),productions:productions.results.map(j=>({...j,result:j.result?rebaseAssetLinks(JSON.parse(j.result),pid):null,publication:publicationByProduction.get(j.id)||null})),jobs:jobs.results,externalActionsEnabled:true};
}

export async function projectMemory(pid:string){await ensureStudioSchema();const row=await database().prepare('SELECT summary,sources,updated_at FROM hub_project_memory WHERE project=?').bind(pid).first<Row>();if(!row)return {projectId:pid,summary:'',sources:[],updatedAt:null};let sources:string[]=[];try{sources=JSON.parse(row.sources);}catch{}return {projectId:pid,summary:row.summary,sources,updatedAt:row.updated_at};}
export async function saveProjectMemory(actor:string,pid:string,summaryValue:unknown,sourcesValue:unknown){await ensureStudioSchema();const summary=text(summaryValue,'프로젝트 기억',18000),sources=Array.isArray(sourcesValue)?sourcesValue.filter(x=>typeof x==='string'&&x.trim()).slice(0,80).map(x=>x.trim().slice(0,240)):[];const now=stamp();await database().prepare('INSERT INTO hub_project_memory(project,summary,sources,updated_by,created_at,updated_at) VALUES(?,?,?,?,?,?) ON CONFLICT(project) DO UPDATE SET summary=excluded.summary,sources=excluded.sources,updated_by=excluded.updated_by,updated_at=excluded.updated_at').bind(pid,summary,JSON.stringify(sources),actor,now,now).run();await event(actor,pid,'project_memory.updated',pid);return {projectId:pid,summary,sources,updatedAt:now};}

export async function studio(req:Request){await ensureStudioSchema();const auth=req.headers.get('authorization')||'';if(!/^Bearer vs_[A-Za-z0-9_-]{43}$/.test(auth))throw new HubError(401,'스튜디오 연결 토큰이 필요합니다.');const key=await database().prepare('SELECT * FROM hub_studio_keys WHERE hash=? AND enabled=1').bind(await hash(auth.slice(7))).first<Row>();if(!key)throw new HubError(401,'스튜디오 연결 토큰이 만료되었거나 폐기됐습니다.');await database().prepare('UPDATE hub_studio_keys SET last_seen=? WHERE id=? AND enabled=1').bind(stamp(),key.id).run();return key;}
export async function studioProgress(pid:string){
 const db=database(),now=Date.now(),interval=5*60*1000;
 const rows=await db.prepare("SELECT j.* FROM hub_production_jobs j JOIN hub_rooms r ON r.id=j.room_id AND r.project=j.project WHERE j.project=? AND r.status!='deleted' AND j.status IN ('queued','running') ORDER BY j.created_at,j.id").bind(pid).all<Row>();
 const rooms=new Map<string,Row[]>();for(const job of rows.results){const list=rooms.get(job.room_id)||[];list.push(job);rooms.set(job.room_id,list);}
 for(const [roomId,jobs]of rooms){
  await db.prepare('INSERT OR IGNORE INTO hub_studio_progress(room_id,project,last_report_ms) VALUES(?,?,?)').bind(roomId,pid,now).run();
  const clock=await db.prepare('SELECT last_report_ms FROM hub_studio_progress WHERE room_id=? AND project=?').bind(roomId,pid).first<Row>();if(!clock||clock.last_report_ms>now-interval)continue;
  const running=jobs.filter(j=>j.status==='running'),queued=jobs.length-running.length;
  const lines=jobs.slice(0,12).map(job=>{let detail:any={};try{detail=JSON.parse(job.result||'{}');}catch{}const state=detail.state==='queued'?'스튜디오 대기':job.status==='queued'?'전달 대기':'제작 중';const note=typeof detail.progress==='string'?detail.progress:typeof detail.message==='string'?detail.message:'';const updated=Date.parse(job.updated_at);return `• ${job.title.slice(0,120)} — ${state}${note?` · ${note.slice(0,220)}`:''}${job.status==='running'&&now-updated>120000?' · 최근 상태 수신 지연':''}`;});
  const message=`스튜디오 진행상황 · 5분 업데이트\n진행 ${running.length}건 · 대기 ${queued}건\n${lines.join('\n')}${jobs.length>12?`\n외 ${jobs.length-12}건`:''}\n완료·오류는 확인되는 즉시 따로 알려드립니다.`;
  // Both statements are one transaction. Concurrent polls cannot duplicate a report.
  await db.batch([
   db.prepare("INSERT INTO hub_studio_progress_reports(id,room_id,project,body,created_at) SELECT ?,?,?,?,? FROM hub_studio_progress WHERE room_id=? AND project=? AND last_report_ms<=?").bind(uid(),roomId,pid,message,stamp(),roomId,pid,now-interval),
   db.prepare('UPDATE hub_studio_progress SET last_report_ms=? WHERE room_id=? AND project=? AND last_report_ms<=?').bind(now,roomId,pid,now-interval),
  ]);
 }
}
