 return {roomId:rid,projectId:(room as Row).project,summary:saved?.summary||'',coveredMessages:saved?.covered_messages||0,throughCursor:saved?.through_cursor||0,updatedAt:saved?.updated_at||null,totalMessages:total?.n||0,scope:'room',summaryMayOmitDetails:true};
